#!/usr/bin/env node
/**
 * figma-fidelity-audit.mjs
 *
 * Auditoria de prontidão e fidelidade para projetos em modo Figma.
 * Verifica:
 * - Artefatos obrigatórios (DESIGN_SYSTEM.md, figma-node-data.json, public/)
 * - Regras críticas nas instructions do projeto
 * - Anti-patterns comuns em código Vue (placeholder, imagens externas, lorem ipsum)
 *
 * Uso:
 *   npm run validate:figma
 *   node node_modules/@dock-tech/shared-copilot-front-lib/scripts/figma-fidelity-audit.mjs --force
 */

import { existsSync, readFileSync, readdirSync, statSync } from 'fs';
import { join, relative } from 'path';

const CWD = process.cwd();
const force = process.argv.includes('--force');
const configPath = join(CWD, 'dock-ds.config.json');

function fail(message) {
  console.error(`❌ ${message}`);
}

function warn(message) {
  console.log(`⚠️  ${message}`);
}

function ok(message) {
  console.log(`✅ ${message}`);
}

function collectFiles(dir, matcher, acc = []) {
  if (!existsSync(dir)) return acc;
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    const stat = statSync(full);
    if (stat.isDirectory() && entry !== 'node_modules' && entry !== 'dist') {
      collectFiles(full, matcher, acc);
    } else if (matcher(full)) {
      acc.push(full);
    }
  }
  return acc;
}

if (!existsSync(configPath)) {
  fail('dock-ds.config.json não encontrado.');
  process.exit(1);
}

const config = JSON.parse(readFileSync(configPath, 'utf-8'));
const figmaConfigured = Boolean(config.figma?.fileId || config.figma?.designSystemDoc);

if (!figmaConfigured && !force) {
  console.log('ℹ️  Projeto sem modo Figma configurado. Nada para auditar.');
  process.exit(0);
}

let hardFailures = 0;
let warnings = 0;

console.log('═'.repeat(60));
console.log('  🔍 Figma Fidelity Audit');
console.log('═'.repeat(60));

const designDoc = config.figma?.designSystemDoc ? join(CWD, config.figma.designSystemDoc) : join(CWD, 'DESIGN_SYSTEM.md');
const nodeData = config.figma?.nodeDataFile ? join(CWD, config.figma.nodeDataFile) : join(CWD, 'figma-node-data.json');
const publicDir = join(CWD, 'public');
const instructionsPath = join(CWD, '.github', 'copilot-instructions.md');

if (existsSync(designDoc)) {
  ok(`DESIGN_SYSTEM.md presente (${relative(CWD, designDoc)})`);
} else {
  fail('DESIGN_SYSTEM.md ausente para modo Figma.');
  hardFailures++;
}

if (existsSync(nodeData)) {
  ok(`figma-node-data.json presente (${relative(CWD, nodeData)})`);
} else {
  warn('figma-node-data.json ausente. Rode npm run figma:sync.');
  warnings++;
}

if (existsSync(publicDir)) {
  ok('Pasta public/ presente para assets do Figma');
} else {
  fail('Pasta public/ ausente. Assets do Figma não terão destino padrão.');
  hardFailures++;
}

if (existsSync(instructionsPath)) {
  const instructions = readFileSync(instructionsPath, 'utf-8').toLowerCase();
  const requiredRules = [
    'design_system.md',
    'pixel',
    'nunca implemente algo que não entendeu',
    'ícones',
    'public/',
    'pergunte',
    'screenshot'
  ];

  const missingRules = requiredRules.filter((rule) => !instructions.includes(rule));
  if (missingRules.length === 0) {
    ok('.github/copilot-instructions.md contém regras críticas do modo Figma');
  } else {
    fail(`Instructions do projeto estão incompletas para modo Figma: ${missingRules.join(', ')}`);
    hardFailures++;
  }
} else {
  fail('.github/copilot-instructions.md ausente.');
  hardFailures++;
}

const vueFiles = collectFiles(join(CWD, 'src'), (file) => file.endsWith('.vue'));
const suspiciousPatterns = [
  { regex: /https?:\/\//gi, label: 'URL externa' },
  { regex: /placeholder/gi, label: 'placeholder' },
  { regex: /lorem ipsum/gi, label: 'lorem ipsum' },
  { regex: /todo/gi, label: 'TODO visual' },
];

for (const file of vueFiles) {
  const content = readFileSync(file, 'utf-8');
  const hits = suspiciousPatterns
    .filter((pattern) => pattern.regex.test(content))
    .map((pattern) => pattern.label);

  if (hits.length > 0) {
    warn(`${relative(CWD, file)} contém sinais de baixa fidelidade: ${hits.join(', ')}`);
    warnings++;
  }
}

console.log('\n' + '─'.repeat(60));
console.log(`Hard failures: ${hardFailures}`);
console.log(`Warnings: ${warnings}`);
console.log('─'.repeat(60));

if (hardFailures > 0) {
  console.log('\n❌ Projeto não está pronto para execução em modo Figma.');
  process.exit(1);
}

console.log('\n✅ Auditoria Figma concluída.');
process.exit(0);
